624	  <script defer>
625	    (() => {
626	      const COLORS = [
627	        { class: 'default', name: 'Default White' },
628	        { class: 'color-mode-1', name: 'Pink' },
629	        { class: 'color-mode-2', name: 'Teal' },
630	        { class: 'color-mode-3', name: 'Mint' },
631	        { class: 'color-mode-4', name: 'Purple' },
632	        { class: 'color-mode-5', name: 'Orange' },
633	        { class: 'color-mode-6', name: 'Coral' },
634	        { class: 'color-mode-7', name: 'Cyan' }
635	      ];
636	
637	      const getRandomColorMode = () => Math.floor(Math.random() * COLORS.length);
638	      const isTouch = (() => {
639	        if (!window.matchMedia) return false;
640	        const hasCoarsePointer = window.matchMedia('(pointer:coarse)').matches;
