655	      const el = {
656	        circle: document.getElementById('decorative-circle'),
657	        hint: document.getElementById('hint-text'),
658	        modeIndicator: document.getElementById('mode-indicator'),
659	        cycleBtn: document.getElementById('cycle-btn'),
660	        randomBtn: document.getElementById('random-btn'),
661	        resetBtn: document.getElementById('reset-btn'),
662	        helpBtn: document.getElementById('help-btn'),
663	        helpModal: document.getElementById('help-modal'),
