667	      let state = { active: false, colorMode: 0 };
668	      let tapCount = 0;
669	      let tapTimeout = null;
670	      let animatingColorShift = false;
671	      let saveTimeout = null;
672	      let lastKeyTime = 0;
673	
674	      const haptic = (duration) => navigator.vibrate?.(duration);
