679	      const storage = {
680	        save() {
681	          clearTimeout(saveTimeout);
682	          saveTimeout = setTimeout(() => {
683	            try {
684	              localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
685	            } catch (e) {
686	              // Silently fail on storage errors
687	            }
688	          }, CONFIG.saveDebounceDuration);
689	        },
690	        load() {
691	          try {
