831	      const handleKeyDown = (e) => {
832	        const key = e.key.toLowerCase();
833	        const handler = keyHandlers[key];
834	        if (!handler) return;
835	
836	        const now = Date.now();
837	        if (now - lastKeyTime < CONFIG.keyDebounce) return;
838	
839	        e.preventDefault();
840	        handler();
841	        lastKeyTime = now;
842	      };
843	
844	      const handleModalKeyDown = (e) => {
